import{_ as s,H as n,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"加餐｜子代理专题总结 & 春节练习","description":"","frontmatter":{},"headers":[{"level":2,"title":"子代理专题总结","slug":"子代理专题总结","link":"#子代理专题总结","children":[]},{"level":2,"title":"各种模式的综合运用：一个完整案例","slug":"各种模式的综合运用-一个完整案例","link":"#各种模式的综合运用-一个完整案例","children":[{"level":3,"title":"第一阶段：并行探索（了解现状）","slug":"第一阶段-并行探索-了解现状","link":"#第一阶段-并行探索-了解现状","children":[]},{"level":3,"title":"第二阶段：高噪声处理（收集线索）","slug":"第二阶段-高噪声处理-收集线索","link":"#第二阶段-高噪声处理-收集线索","children":[]},{"level":3,"title":"第三阶段：假设竞争（Agent Teams 介入）","slug":"第三阶段-假设竞争-agent-teams-介入","link":"#第三阶段-假设竞争-agent-teams-介入","children":[]},{"level":3,"title":"第四阶段：流水线修复（解决问题）","slug":"第四阶段-流水线修复-解决问题","link":"#第四阶段-流水线修复-解决问题","children":[]},{"level":3,"title":"第五阶段：并行验证（确认修复）","slug":"第五阶段-并行验证-确认修复","link":"#第五阶段-并行验证-确认修复","children":[]},{"level":3,"title":"整体编排","slug":"整体编排","link":"#整体编排","children":[]}]},{"level":2,"title":"春节假期作业","slug":"春节假期作业","link":"#春节假期作业","children":[]}],"relativePath":"ClaudeCode工程化实战/加餐｜子代理专题总结&春节练习.md","filePath":"ClaudeCode工程化实战/加餐｜子代理专题总结&春节练习.md","lastUpdated":1779815462000}'),l={name:"ClaudeCode工程化实战/加餐｜子代理专题总结&春节练习.md"};function i(t,a,o,r,c,d){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="加餐-子代理专题总结-春节练习" tabindex="-1">加餐｜子代理专题总结 &amp; 春节练习 <a class="header-anchor" href="#加餐-子代理专题总结-春节练习" aria-label="Permalink to &quot;加餐｜子代理专题总结 &amp; 春节练习&quot;">​</a></h1><p>你好，我是黄佳。春节即将到来，预祝你假期愉快。</p><p>今天的加餐我们对前六讲子代理的专题做个简要总结，并宣布一下假期的安排和练习作业。</p><h2 id="子代理专题总结" tabindex="-1">子代理专题总结 <a class="header-anchor" href="#子代理专题总结" aria-label="Permalink to &quot;子代理专题总结&quot;">​</a></h2><p>经过六讲的学习，你已经掌握了子代理的完整知识体系。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945359/1f0a9f2a6c3b2d700f0f00cfaa059215.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945359/1f0a9f2a6c3b2d700f0f00cfaa059215.jpg" alt=""></a></p><p>我们可以把整个体系分为两层能力：</p><ul><li><p>第一层： <strong>结构化分工（Sub-Agents）</strong></p></li><li><p>第二层： <strong>协作型认知（Agent Teams）</strong></p></li></ul><p><strong>Sub-Agents 解决的是“工程控制问题”，也就是“单脑如何安全分工”。</strong></p><p>之后我们掌握了子代理的四种使用模式。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单独使用</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>┌────────────────────────────┐</span></span>
<span class="line"><span>│  只读型（代码审查）          │</span></span>
<span class="line"><span>│  高噪声（测试/日志）         │</span></span>
<span class="line"><span>└────────────────────────────┘</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>并行 / 流水线</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>┌────────────────────────────┐</span></span>
<span class="line"><span>│  并行探索（独立任务）        │</span></span>
<span class="line"><span>│  流水线编排（依赖任务）      │</span></span>
<span class="line"><span>│  混合模式（部分独立+部分依赖）│</span></span>
<span class="line"><span>└────────────────────────────┘</span></span></code></pre></div><p>Sub-Agents 应用场景是上下文污染 、权限边界 、高噪声干扰 、阶段性分工和可控编排。</p><p><strong>Agent Teams 解决的是“认知协作问题”，也就是多脑如何互相挑战。</strong></p><p>当任务之间不只是 <strong>执行依赖</strong>，而是 <strong>认知依赖</strong> 时，并行已经不够了。</p><p>例如：</p><ul><li><p>多个假设可能互相关联</p></li><li><p>不同视角可能互相推翻</p></li><li><p>架构决策需要立场冲突</p></li><li><p>根因链需要跨模块拼接</p></li></ul><p>这时就要进入 Agent Teams。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                 Team Lead</span></span>
<span class="line"><span>                     │</span></span>
<span class="line"><span>        ┌────────────┼────────────┐</span></span>
<span class="line"><span>        ↓            ↓            ↓</span></span>
<span class="line"><span>    Teammate A  ↔  Teammate B  ↔  Teammate C</span></span></code></pre></div><p>Agent Teams 应用场景是锚定偏见 、单视角误判 、过早收敛和决策质量不足等。</p><h2 id="各种模式的综合运用-一个完整案例" tabindex="-1">各种模式的综合运用：一个完整案例 <a class="header-anchor" href="#各种模式的综合运用-一个完整案例" aria-label="Permalink to &quot;各种模式的综合运用：一个完整案例&quot;">​</a></h2><p>在第 5 至 7 讲，我们学习了四种子代理。让我们用一个完整案例把它们串起来。</p><p><strong>场景</strong>：你的电商系统在大促期间出现了“支付超时”问题，需要排查并修复。</p><h3 id="第一阶段-并行探索-了解现状" tabindex="-1">第一阶段：并行探索（了解现状） <a class="header-anchor" href="#第一阶段-并行探索-了解现状" aria-label="Permalink to &quot;第一阶段：并行探索（了解现状）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同时启动三个只读型探索子代理：</span></span>
<span class="line"><span>├── payment-explorer: 分析支付链路代码</span></span>
<span class="line"><span>├── order-explorer: 分析订单处理流程</span></span>
<span class="line"><span>└── infra-explorer: 分析基础设施配置（超时设置、连接池等）</span></span></code></pre></div><p>这里同时运用了 <strong>并行模式</strong>（三个同时工作）和 <strong>只读型</strong>（只看不改）。</p><h3 id="第二阶段-高噪声处理-收集线索" tabindex="-1">第二阶段：高噪声处理（收集线索） <a class="header-anchor" href="#第二阶段-高噪声处理-收集线索" aria-label="Permalink to &quot;第二阶段：高噪声处理（收集线索）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>启动两个高噪声处理子代理：</span></span>
<span class="line"><span>├── log-analyzer: 分析大促期间的错误日志（可能几万行）</span></span>
<span class="line"><span>└── test-runner: 跑支付相关的测试看看有没有失败</span></span></code></pre></div><p>这里运用了 <strong>高噪声处理模式</strong>——日志和测试输出都是典型的高噪声场景。</p><h3 id="第三阶段-假设竞争-agent-teams-介入" tabindex="-1">第三阶段：假设竞争（Agent Teams 介入） <a class="header-anchor" href="#第三阶段-假设竞争-agent-teams-介入" aria-label="Permalink to &quot;第三阶段：假设竞争（Agent Teams 介入）&quot;">​</a></h3><p>这一步如果只用 Sub-Agents，风险是什么？每个子代理只向主对话汇报。是否会出现 infra 的连接池问题，N+1 查询是否可能存在级联关系。</p><h3 id="第四阶段-流水线修复-解决问题" tabindex="-1">第四阶段：流水线修复（解决问题） <a class="header-anchor" href="#第四阶段-流水线修复-解决问题" aria-label="Permalink to &quot;第四阶段：流水线修复（解决问题）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基于前两阶段的信息，启动修复流水线：</span></span>
<span class="line"><span>Locator → Analyzer → [人工审批] → Fixer → Verifier</span></span></code></pre></div><p>这里运用了 <strong>流水线模式</strong>，并在关键阶段设置人工审批。</p><h3 id="第五阶段-并行验证-确认修复" tabindex="-1">第五阶段：并行验证（确认修复） <a class="header-anchor" href="#第五阶段-并行验证-确认修复" aria-label="Permalink to &quot;第五阶段：并行验证（确认修复）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>修复后，并行验证：</span></span>
<span class="line"><span>├── test-runner: 跑全量测试</span></span>
<span class="line"><span>├── performance-checker: 验证超时是否解决</span></span>
<span class="line"><span>└── code-reviewer: 审查修复代码的质量</span></span></code></pre></div><h3 id="整体编排" tabindex="-1">整体编排 <a class="header-anchor" href="#整体编排" aria-label="Permalink to &quot;整体编排&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Phase 1: Parallel Explore (只读)</span></span>
<span class="line"><span>    ↓ 综合三份探索报告</span></span>
<span class="line"><span>Phase 2: Parallel Noise-filter (只读)</span></span>
<span class="line"><span>    ↓ 综合日志分析和测试结果</span></span>
<span class="line"><span>Phase 3: Hypothesis Debate (Agent Teams)</span></span>
<span class="line"><span>    ↓ 团队协作讨论</span></span>
<span class="line"><span>Phase 4: Sequential Pipeline (读写)</span></span>
<span class="line"><span>    ↓ 修复完成</span></span>
<span class="line"><span>Phase 5: Parallel Verify (只读+执行)</span></span>
<span class="line"><span>    ↓ 确认修复有效</span></span>
<span class="line"><span>Done</span></span></code></pre></div><p><strong>注意每个阶段的权限变化</strong>：只有 Phase 4 的 Fixer 有写权限，其他所有子代理都是只读的。这就是第 3 讲中“最小权限原则”在复杂场景中的体现。</p><p><strong>贯穿始终的工程方法论</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 5 讲的方法论：痛点驱动设计（痛点→缺什么→选机制→画边界→验证）</span></span>
<span class="line"><span>第 6 讲的方法论：信噪比框架 + 输出格式设计 + 模型选择验证</span></span>
<span class="line"><span>第 7 讲的方法论：交接契约 + 编排者决策 + 混合模式选型</span></span>
<span class="line"><span></span></span>
<span class="line"><span>共同主线：不是&quot;学会配置子代理&quot;，而是&quot;面对任何工程场景，</span></span>
<span class="line"><span>         能判断是否需要子代理、需要什么样的子代理、如何组合它们&quot;</span></span></code></pre></div><h2 id="春节假期作业" tabindex="-1"><strong>春节假期作业</strong> <a class="header-anchor" href="#春节假期作业" aria-label="Permalink to &quot;**春节假期作业**&quot;">​</a></h2><p>春节即将到来，预祝你假期愉快。按照我们的课程安排，春节假期（2.16～2.22）这一周会暂停更新，你可以利用这个时间回顾前面的课程，查漏补缺。这里我也准备了两个综合性的思考题与你探讨。假期之后，我们将开启“ <strong>Skills 技能系统</strong>”的学习，敬请期待。</p><ol><li>参考“各种模式的综合运用”案例，为你自己项目中的一个复杂问题设计完整的子代理编排方案。要求：</li></ol><ul><li><p>明确用了哪些模式</p></li><li><p>标注每个子代理的权限</p></li><li><p>标注人工介入点</p></li></ul><ol start="2"><li>回到“电商大促支付超时”这个完整案例，假设 <strong>不使用任何子代理</strong>，而是只在主对话中让 AI 一步步帮你排查和修复，请回答：</li></ol><ul><li><p>在 Phase 1（问题探索） 阶段，哪些信息最容易被遗漏或相互覆盖？为什么？</p></li><li><p>在 Phase 2（日志 / 测试分析） 阶段，高噪声输出会对后续判断产生哪些具体干扰？</p></li><li><p>在 Phase 4（修复阶段），如果没有权限隔离，AI“好心修改”可能带来哪些工程风险？</p></li><li><p>从审计、回滚、团队协作的角度看，这种“单对话全包”的方式有哪些不可控点？</p></li></ul><p>最后，请用一句话总结： <strong>子代理真正解决的是不是“能力问题”，还是哪一类“工程风险”？</strong></p>`,47)])])}const u=s(l,[["render",i]]);export{g as __pageData,u as default};
